from datetime import date, timedelta
from typing import Optional

def expand(rule: dict, dtstart: date, limit: int) -> list[date]:
    """
    Expand a recurrence rule starting from dtstart up to limit occurrences.

    Args:
        rule: Dictionary with FREQ (required), INTERVAL, COUNT, UNTIL, BYMONTH,
              BYMONTHDAY, BYDAY
        dtstart: Starting date (inclusive if it matches pattern)
        limit: Maximum number of dates to return

    Returns:
        List of dates in ascending order

    Raises:
        ValueError: For invalid rule parameters
    """
    # Parse and validate rule
    freq = rule.get('FREQ')
    if freq not in ('DAILY', 'WEEKLY', 'MONTHLY'):
        raise ValueError(f"Unknown FREQ: {freq}")

    interval = rule.get('INTERVAL', 1)
    if not isinstance(interval, int) or interval < 1:
        raise ValueError(f"INTERVAL must be int >= 1")

    count = rule.get('COUNT')
    until = rule.get('UNTIL')
    bymonth = rule.get('BYMONTH')
    bymonthday = rule.get('BYMONTHDAY')
    byday = rule.get('BYDAY')

    # Validate BYMONTHDAY
    if bymonthday:
        for day in bymonthday:
            if not isinstance(day, int) or day == 0 or day < -31 or day > 31:
                raise ValueError(f"BYMONTHDAY out of range")

    # Check for invalid combination
    if freq == 'MONTHLY' and bymonthday and byday:
        raise ValueError("MONTHLY may not combine BYMONTHDAY and BYDAY")

    # Validate BYDAY
    weekday_map = {'MO': 0, 'TU': 1, 'WE': 2, 'TH': 3, 'FR': 4, 'SA': 5, 'SU': 6}
    if byday:
        for day_spec in byday:
            if freq == 'WEEKLY':
                if day_spec not in weekday_map:
                    raise ValueError(f"Unknown weekday code")
            elif freq == 'MONTHLY':
                if len(day_spec) < 3:
                    raise ValueError(f"Malformed BYDAY for MONTHLY")
                ordinal_str = day_spec[:-2]
                weekday_code = day_spec[-2:]
                try:
                    ordinal = int(ordinal_str)
                except ValueError:
                    raise ValueError(f"Malformed BYDAY ordinal")
                if ordinal == 0 or ordinal < -5 or ordinal > 5:
                    raise ValueError(f"BYDAY ordinal out of range")
                if weekday_code not in weekday_map:
                    raise ValueError(f"Unknown weekday code")

    result = []

    if freq == 'DAILY':
        current = dtstart
        while len(result) < limit and (count is None or len(result) < count):
            if until and current > until:
                break
            if bymonth is None or current.month in bymonth:
                result.append(current)
            current += timedelta(days=interval)

    elif freq == 'WEEKLY':
        if byday is None:
            target_weekdays = [dtstart.weekday()]
        else:
            target_weekdays = [weekday_map[day] for day in byday]

        # Compute the week start of dtstart (Monday = day 0)
        dtstart_week_start = dtstart - timedelta(days=dtstart.weekday())

        current = dtstart
        occurrences_count = 0

        while occurrences_count < limit and (count is None or occurrences_count < count):
            if until and current > until:
                break

            # Check if current is in an active week
            week_start = current - timedelta(days=current.weekday())
            days_since_dtstart_week = (week_start - dtstart_week_start).days

            if days_since_dtstart_week >= 0 and days_since_dtstart_week % (interval * 7) == 0:
                if current.weekday() in target_weekdays:
                    if bymonth is None or current.month in bymonth:
                        result.append(current)
                        occurrences_count += 1

            current += timedelta(days=1)

    elif freq == 'MONTHLY':
        current_year = dtstart.year
        current_month = dtstart.month
        occurrences_count = 0

        while occurrences_count < limit and (count is None or occurrences_count < count):
            # Check if current month is active
            months_since_start = (current_year - dtstart.year) * 12 + (current_month - dtstart.month)

            if months_since_start >= 0 and months_since_start % interval == 0:
                if bymonth is None or current_month in bymonth:
                    # Generate dates for this month
                    month_dates = []

                    if bymonthday:
                        for day_spec in bymonthday:
                            actual_day = _get_month_day(current_year, current_month, day_spec)
                            if actual_day:
                                month_dates.append(date(current_year, current_month, actual_day))
                    elif byday:
                        for day_spec in byday:
                            ordinal_str = day_spec[:-2]
                            weekday_code = day_spec[-2:]
                            ordinal = int(ordinal_str)
                            actual_day = _get_ordinal_weekday(current_year, current_month, ordinal, weekday_map[weekday_code])
                            if actual_day:
                                month_dates.append(actual_day)
                    else:
                        # Use day-of-month of dtstart
                        actual_day = _get_month_day(current_year, current_month, dtstart.day)
                        if actual_day:
                            month_dates.append(date(current_year, current_month, actual_day))

                    # Add dates that are >= dtstart and <= until, in order
                    for d in sorted(set(month_dates)):
                        if d >= dtstart and (until is None or d <= until):
                            result.append(d)
                            occurrences_count += 1
                            if occurrences_count >= limit or (count is not None and occurrences_count >= count):
                                break

            # Move to next month
            if current_month == 12:
                current_month = 1
                current_year += 1
            else:
                current_month += 1

            # Stop if we've gone past UNTIL
            if until and date(current_year, current_month, 1) > until:
                break

    return result


def _get_month_day(year: int, month: int, day: int) -> Optional[int]:
    """Convert a day specification (positive or negative) to an actual day in the month."""
    if day > 0:
        if day > 31:
            return None
        # Check if day exists in this month
        days_in_month = _days_in_month(year, month)
        if day > days_in_month:
            return None
        return day
    else:
        # Negative day (from end of month)
        days_in_month = _days_in_month(year, month)
        actual_day = days_in_month + day + 1
        if actual_day < 1:
            return None
        return actual_day


def _is_leap_year(year: int) -> bool:
    """Check if a year is a leap year."""
    return (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)


def _days_in_month(year: int, month: int) -> int:
    """Return number of days in a given month."""
    if month == 2:
        return 29 if _is_leap_year(year) else 28
    elif month in (4, 6, 9, 11):
        return 30
    else:
        return 31


def _get_ordinal_weekday(year: int, month: int, ordinal: int, target_weekday: int) -> Optional[date]:
    """
    Get the ordinal weekday in a month.

    Args:
        ordinal: 1-5 for first-fifth, -1 to -5 for last-fifth
        target_weekday: 0=Monday, 6=Sunday

    Returns:
        The date if it exists, None otherwise
    """
    # Find all dates in the month that match the weekday
    days = []
    for day in range(1, _days_in_month(year, month) + 1):
        d = date(year, month, day)
        if d.weekday() == target_weekday:
            days.append(d)

    if ordinal > 0:
        if ordinal > len(days):
            return None
        return days[ordinal - 1]
    else:
        if -ordinal > len(days):
            return None
        return days[ordinal]

"""RRULE-lite: a small recurrence rule expander (standard library only)."""

import calendar
import datetime
import re

_WEEKDAY_MAP = {
    "MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6,
}

_WEEKLY_TOKEN_RE = re.compile(r"^(MO|TU|WE|TH|FR|SA|SU)$")
_MONTHLY_TOKEN_RE = re.compile(r"^([+-]?\d+)(MO|TU|WE|TH|FR|SA|SU)$")

_MAX_PERIODS = 20000  # safety cap to avoid runaway loops on unreachable COUNT


def _is_plain_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def expand(rule, dtstart, limit):
    freq = rule.get("FREQ")
    if freq not in ("DAILY", "WEEKLY", "MONTHLY"):
        raise ValueError("unknown FREQ: %r" % (freq,))

    interval = rule.get("INTERVAL", 1)
    if not _is_plain_int(interval) or interval < 1:
        raise ValueError("INTERVAL must be an int >= 1")

    count = rule.get("COUNT")
    if count is not None:
        if not _is_plain_int(count) or count < 1:
            raise ValueError("COUNT must be an int >= 1")

    until = rule.get("UNTIL")
    if until is not None and not isinstance(until, datetime.date):
        raise ValueError("UNTIL must be a datetime.date")

    bymonth = rule.get("BYMONTH")
    if bymonth is not None:
        bymonth = list(bymonth)
        for m in bymonth:
            if not _is_plain_int(m) or m < 1 or m > 12:
                raise ValueError("BYMONTH values must be ints in 1..12")
        bymonth_set = set(bymonth)
    else:
        bymonth_set = None

    bymonthday = rule.get("BYMONTHDAY")
    if bymonthday is not None:
        bymonthday = list(bymonthday)
        if freq != "MONTHLY":
            raise ValueError("BYMONTHDAY is only valid with FREQ=MONTHLY")
        for n in bymonthday:
            if not _is_plain_int(n) or n == 0 or n < -31 or n > 31:
                raise ValueError("BYMONTHDAY values must be in 1..31 or -31..-1")

    byday = rule.get("BYDAY")
    parsed_byday = None
    if byday is not None:
        byday = list(byday)
        if freq == "WEEKLY":
            parsed = []
            for tok in byday:
                if not isinstance(tok, str):
                    raise ValueError("malformed BYDAY token: %r" % (tok,))
                m = _WEEKLY_TOKEN_RE.match(tok)
                if not m:
                    raise ValueError("malformed BYDAY token for WEEKLY: %r" % (tok,))
                parsed.append(_WEEKDAY_MAP[m.group(1)])
            parsed_byday = parsed
        elif freq == "MONTHLY":
            parsed = []
            for tok in byday:
                if not isinstance(tok, str):
                    raise ValueError("malformed BYDAY token: %r" % (tok,))
                m = _MONTHLY_TOKEN_RE.match(tok)
                if not m:
                    raise ValueError("malformed BYDAY token for MONTHLY: %r" % (tok,))
                ordinal = int(m.group(1))
                if ordinal == 0 or ordinal < -5 or ordinal > 5:
                    raise ValueError("BYDAY ordinal out of range: %r" % (tok,))
                parsed.append((ordinal, _WEEKDAY_MAP[m.group(2)]))
            parsed_byday = parsed
        else:
            parsed_byday = None  # BYDAY unused/undefined for DAILY

    if freq == "MONTHLY" and bymonthday is not None and byday is not None:
        raise ValueError("MONTHLY cannot combine BYMONTHDAY and BYDAY")

    result = []
    target = limit if count is None else min(limit, count)
    if target <= 0:
        return result

    if freq == "DAILY":
        _expand_daily(dtstart, interval, until, bymonth_set, result, target)
    elif freq == "WEEKLY":
        _expand_weekly(dtstart, interval, until, bymonth_set, parsed_byday, result, target)
    elif freq == "MONTHLY":
        _expand_monthly(dtstart, interval, until, bymonth_set, bymonthday, parsed_byday,
                         result, target)

    return result


def _passes_bymonth(d, bymonth_set):
    return bymonth_set is None or d.month in bymonth_set


def _expand_daily(dtstart, interval, until, bymonth_set, result, target):
    d = dtstart
    step = datetime.timedelta(days=interval)
    periods = 0
    while len(result) < target and periods < _MAX_PERIODS:
        if until is not None and d > until:
            break
        if _passes_bymonth(d, bymonth_set):
            result.append(d)
        d = d + step
        periods += 1


def _week_monday(d):
    return d - datetime.timedelta(days=d.weekday())


def _expand_weekly(dtstart, interval, until, bymonth_set, parsed_byday, result, target):
    anchor_monday = _week_monday(dtstart)
    weekday_codes = parsed_byday if parsed_byday is not None else [dtstart.weekday()]
    weekday_codes = sorted(set(weekday_codes))

    w = 0
    while len(result) < target and w < _MAX_PERIODS:
        week_monday = anchor_monday + datetime.timedelta(weeks=w * interval)
        if until is not None and week_monday > until:
            break
        candidates = []
        for wc in weekday_codes:
            candidates.append(week_monday + datetime.timedelta(days=wc))
        candidates = sorted(set(candidates))
        stop_all = False
        for d in candidates:
            if d < dtstart:
                continue
            if until is not None and d > until:
                stop_all = True
                break
            if _passes_bymonth(d, bymonth_set):
                result.append(d)
                if len(result) >= target:
                    break
        if stop_all:
            break
        w += 1


def _add_months(year, month, n):
    total = (year * 12 + (month - 1)) + n
    y, m0 = divmod(total, 12)
    return y, m0 + 1


def _nth_weekday_of_month(year, month, weekday, ordinal):
    days_in_month = calendar.monthrange(year, month)[1]
    if ordinal > 0:
        first_day = datetime.date(year, month, 1)
        first_weekday = first_day.weekday()
        offset = (weekday - first_weekday) % 7
        day = 1 + offset + (ordinal - 1) * 7
        if day > days_in_month:
            return None
        return datetime.date(year, month, day)
    else:
        last_day_num = days_in_month
        last_weekday = datetime.date(year, month, last_day_num).weekday()
        offset = (last_weekday - weekday) % 7
        day = last_day_num - offset - (abs(ordinal) - 1) * 7
        if day < 1:
            return None
        return datetime.date(year, month, day)


def _monthday_to_date(year, month, n):
    days_in_month = calendar.monthrange(year, month)[1]
    if n > 0:
        if n > days_in_month:
            return None
        return datetime.date(year, month, n)
    else:
        day = days_in_month + n + 1
        if day < 1:
            return None
        return datetime.date(year, month, day)


def _expand_monthly(dtstart, interval, until, bymonth_set, bymonthday, parsed_byday,
                     result, target):
    anchor_year, anchor_month = dtstart.year, dtstart.month
    mi = 0
    while len(result) < target and mi < _MAX_PERIODS:
        year, month = _add_months(anchor_year, anchor_month, mi * interval)
        month_start = datetime.date(year, month, 1)
        if until is not None and month_start > until:
            break

        candidates = []
        if bymonthday is not None:
            for n in bymonthday:
                d = _monthday_to_date(year, month, n)
                if d is not None:
                    candidates.append(d)
        elif parsed_byday is not None:
            for ordinal, weekday in parsed_byday:
                d = _nth_weekday_of_month(year, month, weekday, ordinal)
                if d is not None:
                    candidates.append(d)
        else:
            days_in_month = calendar.monthrange(year, month)[1]
            if dtstart.day <= days_in_month:
                candidates.append(datetime.date(year, month, dtstart.day))

        candidates = sorted(set(candidates))
        stop_all = False
        for d in candidates:
            if d < dtstart:
                continue
            if until is not None and d > until:
                stop_all = True
                break
            if _passes_bymonth(d, bymonth_set):
                result.append(d)
                if len(result) >= target:
                    break
        if stop_all:
            break
        mi += 1

import calendar
import datetime

_WEEKDAYS = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}
_FREQS = {"DAILY", "WEEKLY", "MONTHLY"}
_MAX_PERIODS = 500000


def _days_in_month(year, month):
    return calendar.monthrange(year, month)[1]


def _add_months(year, month, n):
    idx = (year * 12 + (month - 1)) + n
    return idx // 12, idx % 12 + 1


def _parse_byday(tokens, freq):
    """Return list of (ordinal_or_None, weekday_index) tuples, preserving order."""
    result = []
    for tok in tokens:
        if not isinstance(tok, str):
            raise ValueError("bad BYDAY token")
        t = tok.strip().upper()
        if len(t) < 2:
            raise ValueError("bad BYDAY token: %r" % tok)
        code = t[-2:]
        if code not in _WEEKDAYS:
            raise ValueError("unknown weekday code: %r" % tok)
        wd = _WEEKDAYS[code]
        prefix = t[:-2]
        if freq == "WEEKLY":
            if prefix != "":
                raise ValueError("WEEKLY BYDAY may not have an ordinal: %r" % tok)
            result.append((None, wd))
        else:  # MONTHLY
            if prefix == "":
                raise ValueError("MONTHLY BYDAY requires an ordinal: %r" % tok)
            try:
                ordv = int(prefix)
            except ValueError:
                raise ValueError("bad BYDAY ordinal: %r" % tok)
            if ordv == 0 or ordv < -5 or ordv > 5:
                raise ValueError("BYDAY ordinal out of range: %r" % tok)
            result.append((ordv, wd))
    return result


def _validate_bymonthday(values):
    for v in values:
        if not isinstance(v, int) or isinstance(v, bool):
            raise ValueError("bad BYMONTHDAY value: %r" % v)
        if v == 0 or v < -31 or v > 31:
            raise ValueError("BYMONTHDAY value out of range: %r" % v)


def _resolve_monthday(year, month, n):
    dim = _days_in_month(year, month)
    if n > 0:
        day = n
    else:
        day = dim + n + 1
    if day < 1 or day > dim:
        return None
    return datetime.date(year, month, day)


def _resolve_ordinal_weekday(year, month, ordv, wd):
    dim = _days_in_month(year, month)
    if ordv > 0:
        first_wd = datetime.date(year, month, 1).weekday()
        first_match = 1 + (wd - first_wd) % 7
        day = first_match + 7 * (ordv - 1)
    else:
        last_wd = datetime.date(year, month, dim).weekday()
        last_match = dim - (last_wd - wd) % 7
        day = last_match - 7 * (-ordv - 1)
    if day < 1 or day > dim:
        return None
    return datetime.date(year, month, day)


def _daily_candidates(dtstart, interval):
    count = 0
    d = dtstart
    while count < _MAX_PERIODS:
        yield d
        if (datetime.date.max - d).days < interval:
            return
        d = d + datetime.timedelta(days=interval)
        count += 1


def _weekly_candidates(dtstart, interval, byday):
    if byday:
        wds = sorted(set(wd for (_, wd) in byday))
    else:
        wds = [dtstart.weekday()]
    start_monday = dtstart - datetime.timedelta(days=dtstart.weekday())
    period = 0
    while period < _MAX_PERIODS:
        offset = interval * period * 7
        if (datetime.date.max - start_monday).days < offset:
            return
        monday = start_monday + datetime.timedelta(days=offset)
        for wd in wds:
            d = monday + datetime.timedelta(days=wd)
            if d > datetime.date.max:
                break
            if d >= dtstart:
                yield d
        period += 1


def _monthly_candidates(dtstart, interval, byday, bymonthday):
    period = 0
    while period < _MAX_PERIODS:
        year, month = _add_months(dtstart.year, dtstart.month, interval * period)
        if year > datetime.MAXYEAR:
            return
        found = []
        if bymonthday:
            for n in bymonthday:
                d = _resolve_monthday(year, month, n)
                if d is not None:
                    found.append(d)
        elif byday:
            for (ordv, wd) in byday:
                d = _resolve_ordinal_weekday(year, month, ordv, wd)
                if d is not None:
                    found.append(d)
        else:
            dim = _days_in_month(year, month)
            if dtstart.day <= dim:
                found.append(datetime.date(year, month, dtstart.day))
        for d in sorted(set(found)):
            if d >= dtstart:
                yield d
        period += 1


def expand(rule, dtstart, limit):
    freq = rule.get("FREQ")
    if freq not in _FREQS:
        raise ValueError("unknown FREQ: %r" % (freq,))

    interval = rule.get("INTERVAL", 1)
    if not isinstance(interval, int) or isinstance(interval, bool) or interval < 1:
        raise ValueError("INTERVAL must be an int >= 1")

    count = rule.get("COUNT")
    until = rule.get("UNTIL")
    bymonth = rule.get("BYMONTH")
    bymonthday_raw = rule.get("BYMONTHDAY")
    byday_raw = rule.get("BYDAY")

    byday = None
    if byday_raw is not None:
        byday = _parse_byday(byday_raw, freq)

    bymonthday = None
    if bymonthday_raw is not None:
        _validate_bymonthday(bymonthday_raw)
        bymonthday = list(bymonthday_raw)

    if freq == "MONTHLY" and bymonthday and byday:
        raise ValueError("MONTHLY may not combine BYMONTHDAY and BYDAY")

    bymonth_set = set(bymonth) if bymonth else None

    if freq == "DAILY":
        gen = _daily_candidates(dtstart, interval)
    elif freq == "WEEKLY":
        gen = _weekly_candidates(dtstart, interval, byday)
    else:
        gen = _monthly_candidates(dtstart, interval, byday, bymonthday)

    target = limit
    if count is not None:
        target = min(target, count)

    result = []
    if target <= 0:
        return result
    for d in gen:
        if d < dtstart:
            continue
        if until is not None and d > until:
            break
        if bymonth_set is not None and d.month not in bymonth_set:
            continue
        result.append(d)
        if len(result) >= target:
            break
    return result

"""RRULE-lite: a small recurrence-rule expander (standard library only)."""

import calendar
import re
from datetime import date, timedelta

_FREQS = ("DAILY", "WEEKLY", "MONTHLY")
_WEEKDAYS = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}
_ORDINAL_TOKEN = re.compile(r"^([+-]?\d+)([A-Z]{2})$")


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _parse_plain_byday(tokens):
    """WEEKLY/DAILY BYDAY: plain two-letter codes only, no ordinal allowed."""
    days = set()
    for tok in tokens:
        if not isinstance(tok, str) or tok not in _WEEKDAYS:
            raise ValueError("malformed BYDAY token: %r" % (tok,))
        days.add(_WEEKDAYS[tok])
    return sorted(days)


def _parse_ordinal_byday(tokens):
    """MONTHLY BYDAY: ordinal weekday tokens like '2TU' or '-1FR'."""
    entries = []
    for tok in tokens:
        if not isinstance(tok, str):
            raise ValueError("malformed BYDAY token: %r" % (tok,))
        m = _ORDINAL_TOKEN.match(tok)
        if m is None:
            raise ValueError("malformed BYDAY token: %r" % (tok,))
        ordinal = int(m.group(1))
        code = m.group(2)
        if code not in _WEEKDAYS:
            raise ValueError("unknown weekday code in BYDAY token: %r" % (tok,))
        if ordinal == 0 or not (-5 <= ordinal <= 5):
            raise ValueError("BYDAY ordinal out of range in token: %r" % (tok,))
        entries.append((ordinal, _WEEKDAYS[code]))
    return entries


def _nth_weekday_day(year, month, dim, ordinal, weekday):
    """Day-of-month of the ordinal-th `weekday` in year/month, or None."""
    if ordinal > 0:
        first_wd = date(year, month, 1).weekday()
        day = 1 + (weekday - first_wd) % 7 + (ordinal - 1) * 7
        return day if day <= dim else None
    last_wd = date(year, month, dim).weekday()
    day = dim - (last_wd - weekday) % 7 + (ordinal + 1) * 7
    return day if day >= 1 else None


def _candidates(freq, interval, dtstart, byday, bymonthday):
    """Yield pattern dates in ascending order (may include dates < dtstart
    for the first WEEKLY/MONTHLY period). Stops at the calendar's end."""
    if freq == "DAILY":
        step = timedelta(days=interval)
        d = dtstart
        while True:
            if byday is None or d.weekday() in byday:
                yield d
            try:
                d = d + step
            except OverflowError:
                return
    elif freq == "WEEKLY":
        weekdays = byday if byday is not None else [dtstart.weekday()]
        ws = dtstart - timedelta(days=dtstart.weekday())  # Monday of week
        step = timedelta(weeks=interval)
        while True:
            try:
                for wd in weekdays:
                    yield ws + timedelta(days=wd)
                ws = ws + step
            except OverflowError:
                return
    else:  # MONTHLY
        base = dtstart.year * 12 + (dtstart.month - 1)
        k = 0
        while True:
            idx = base + k * interval
            year, month0 = divmod(idx, 12)
            if year > 9999:
                return
            month = month0 + 1
            dim = calendar.monthrange(year, month)[1]
            days = set()
            if bymonthday is not None:
                for n in bymonthday:
                    day = n if n > 0 else dim + 1 + n
                    if (n > 0 and day <= dim) or (n < 0 and day >= 1):
                        days.add(day)
            elif byday is not None:
                for ordinal, wd in byday:
                    day = _nth_weekday_day(year, month, dim, ordinal, wd)
                    if day is not None:
                        days.add(day)
            else:
                if dtstart.day <= dim:
                    days.add(dtstart.day)
            for day in sorted(days):
                yield date(year, month, day)
            k += 1


def expand(rule, dtstart, limit):
    """Expand an RRULE-lite `rule` anchored at `dtstart` into a sorted list
    of at most `limit` datetime.date occurrences."""
    freq = rule.get("FREQ")
    if freq not in _FREQS:
        raise ValueError("unknown or missing FREQ: %r" % (freq,))

    interval = rule.get("INTERVAL", 1)
    if not _is_int(interval) or interval < 1:
        raise ValueError("INTERVAL must be an int >= 1: %r" % (interval,))

    bymonth = rule.get("BYMONTH") or None
    if bymonth is not None:
        months = set()
        for m in bymonth:
            if not _is_int(m) or not 1 <= m <= 12:
                raise ValueError("BYMONTH value out of range: %r" % (m,))
            months.add(m)
        bymonth = months

    byday = rule.get("BYDAY") or None
    bymonthday = rule.get("BYMONTHDAY") or None

    if bymonthday is not None:
        if freq != "MONTHLY":
            raise ValueError("BYMONTHDAY is only valid with FREQ=MONTHLY")
        if byday is not None:
            raise ValueError("MONTHLY may not combine BYMONTHDAY and BYDAY")
        mdays = []
        for n in bymonthday:
            if not _is_int(n) or n == 0 or not -31 <= n <= 31:
                raise ValueError("BYMONTHDAY value out of range: %r" % (n,))
            mdays.append(n)
        bymonthday = mdays

    if byday is not None:
        if freq == "MONTHLY":
            byday = _parse_ordinal_byday(byday)
        else:
            byday = _parse_plain_byday(byday)

    count = rule.get("COUNT")
    until = rule.get("UNTIL")

    target = limit
    if count is not None:
        target = min(target, count)

    result = []
    if target <= 0:
        return result

    for cand in _candidates(freq, interval, dtstart, byday, bymonthday):
        if cand < dtstart:
            continue
        if until is not None and cand > until:
            break
        if bymonth is not None and cand.month not in bymonth:
            continue
        result.append(cand)
        if len(result) >= target:
            break
    return result

"""RRULE-lite recurrence expander (standard library only)."""

import datetime
import calendar

WEEKDAYS = ["MO", "TU", "WE", "TH", "FR", "SA", "SU"]


def _parse_byday_weekly(tokens):
    result = []
    for tok in tokens:
        i = 0
        while i < len(tok) and (tok[i].isdigit() or tok[i] in "+-"):
            i += 1
        num_part = tok[:i]
        code = tok[i:]
        if num_part != "":
            raise ValueError(f"WEEKLY BYDAY must not have an ordinal: {tok}")
        if code not in WEEKDAYS:
            raise ValueError(f"Unknown weekday code: {tok}")
        result.append(WEEKDAYS.index(code))
    return result


def _parse_byday_monthly(tokens):
    result = []
    for tok in tokens:
        i = 0
        while i < len(tok) and (tok[i].isdigit() or tok[i] in "+-"):
            i += 1
        num_part = tok[:i]
        code = tok[i:]
        if code not in WEEKDAYS:
            raise ValueError(f"Unknown weekday code: {tok}")
        if num_part == "" or num_part == "+" or num_part == "-":
            raise ValueError(f"MONTHLY BYDAY requires an ordinal: {tok}")
        try:
            n = int(num_part)
        except ValueError:
            raise ValueError(f"Malformed ordinal in BYDAY token: {tok}")
        if n == 0 or n < -5 or n > 5:
            raise ValueError(f"BYDAY ordinal out of range: {tok}")
        result.append((n, WEEKDAYS.index(code)))
    return result


def _week_start(d):
    return d - datetime.timedelta(days=d.weekday())


def _add_months(year, month0, delta):
    total = year * 12 + month0 + delta
    return total // 12, total % 12


def _nth_weekday_of_month(year, month, n, weekday):
    """n: nonzero ordinal (1-based from start, negative from end). weekday: 0=Mon..6=Sun."""
    days_in_month = calendar.monthrange(year, month)[1]
    matches = [
        d for d in range(1, days_in_month + 1)
        if datetime.date(year, month, d).weekday() == weekday
    ]
    if n > 0:
        if n - 1 < len(matches):
            return matches[n - 1]
        return None
    else:
        idx = len(matches) + n
        if 0 <= idx < len(matches):
            return matches[idx]
        return None


def _monthday_to_day(year, month, n):
    days_in_month = calendar.monthrange(year, month)[1]
    if n > 0:
        if n <= days_in_month:
            return n
        return None
    else:
        day = days_in_month + n + 1
        if day >= 1:
            return day
        return None


def expand(rule: dict, dtstart: datetime.date, limit: int) -> list:
    freq = rule.get("FREQ")
    if freq not in ("DAILY", "WEEKLY", "MONTHLY"):
        raise ValueError(f"Unknown FREQ: {freq}")

    interval = rule.get("INTERVAL", 1)
    if not isinstance(interval, int) or isinstance(interval, bool) or interval < 1:
        raise ValueError("INTERVAL must be an int >= 1")

    count = rule.get("COUNT")
    if count is not None:
        if not isinstance(count, int) or isinstance(count, bool) or count < 1:
            raise ValueError("COUNT must be an int >= 1")

    until = rule.get("UNTIL")

    bymonth = rule.get("BYMONTH")
    if bymonth is not None:
        for m in bymonth:
            if not isinstance(m, int) or m < 1 or m > 12:
                raise ValueError(f"Invalid BYMONTH value: {m}")
        bymonth = set(bymonth)

    bymonthday = rule.get("BYMONTHDAY")
    byday = rule.get("BYDAY")

    if bymonthday is not None and freq != "MONTHLY":
        raise ValueError("BYMONTHDAY only valid for MONTHLY")

    if bymonthday is not None and byday is not None and freq == "MONTHLY":
        raise ValueError("Cannot combine BYMONTHDAY and BYDAY in MONTHLY")

    if bymonthday is not None:
        for n in bymonthday:
            if not isinstance(n, int) or n == 0 or n < -31 or n > 31:
                raise ValueError(f"Invalid BYMONTHDAY value: {n}")

    parsed_byday_weekly = None
    parsed_byday_monthly = None
    if byday is not None:
        if freq == "WEEKLY":
            parsed_byday_weekly = _parse_byday_weekly(byday)
        elif freq == "MONTHLY":
            parsed_byday_monthly = _parse_byday_monthly(byday)

    results = []

    def emit(d):
        if d < dtstart:
            return False
        if until is not None and d > until:
            return False
        if bymonth is not None and d.month not in bymonth:
            return False
        results.append(d)
        return True

    def done():
        if len(results) >= limit:
            return True
        if count is not None and len(results) >= count:
            return True
        return False

    if until is not None and until < dtstart:
        return []

    if freq == "DAILY":
        d = dtstart
        while not done():
            if until is not None and d > until:
                break
            candidate_ok = True
            if bymonth is not None and d.month not in bymonth:
                candidate_ok = False
            if candidate_ok:
                emit(d)
                if done():
                    break
            d = d + datetime.timedelta(days=interval)
        return results[: (min(limit, count) if count is not None else limit)]

    if freq == "WEEKLY":
        weekdays_needed = parsed_byday_weekly if parsed_byday_weekly is not None else [dtstart.weekday()]
        weekdays_needed = sorted(set(weekdays_needed))
        start_week = _week_start(dtstart)
        week_num = 0
        while not done():
            week_start = start_week + datetime.timedelta(weeks=week_num * interval)
            if until is not None and week_start > until:
                break
            for wd in weekdays_needed:
                d = week_start + datetime.timedelta(days=wd)
                if d < dtstart:
                    continue
                if until is not None and d > until:
                    continue
                if bymonth is not None and d.month not in bymonth:
                    continue
                results.append(d)
                if done():
                    break
            week_num += 1
            if until is None and week_num > 100000:
                break
        return results[: (min(limit, count) if count is not None else limit)]

    if freq == "MONTHLY":
        start_year = dtstart.year
        start_month0 = dtstart.month - 1
        month_idx = 0
        while not done():
            year, month0 = _add_months(start_year, start_month0, month_idx * interval)
            month = month0 + 1
            if until is not None:
                first_of_month = datetime.date(year, month, 1)
                if first_of_month > until:
                    break

            day_candidates = []
            if parsed_byday_monthly is not None:
                for (n, wd) in parsed_byday_monthly:
                    day = _nth_weekday_of_month(year, month, n, wd)
                    if day is not None:
                        day_candidates.append(day)
            elif bymonthday is not None:
                for n in bymonthday:
                    day = _monthday_to_day(year, month, n)
                    if day is not None:
                        day_candidates.append(day)
            else:
                dom = dtstart.day
                days_in_month = calendar.monthrange(year, month)[1]
                if dom <= days_in_month:
                    day_candidates.append(dom)

            day_candidates = sorted(set(day_candidates))
            for day in day_candidates:
                d = datetime.date(year, month, day)
                if d < dtstart:
                    continue
                if until is not None and d > until:
                    continue
                if bymonth is not None and d.month not in bymonth:
                    continue
                results.append(d)
                if done():
                    break

            month_idx += 1
            if until is None and month_idx > 1000000:
                break
        return results[: (min(limit, count) if count is not None else limit)]

    return results

"""RRULE-lite: a small recurrence-rule expander (standard library only).

Public API:

    expand(rule, dtstart, limit) -> list[datetime.date]

Returns, in ascending order, the first occurrences of the recurrence
described by ``rule`` starting at ``dtstart``.
"""

import calendar
import datetime

__all__ = ["expand"]

_WEEKDAY = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}
_FREQ = ("DAILY", "WEEKLY", "MONTHLY")
_MAX_YEAR = 9999  # datetime.date cannot represent later years


def _weekly_weekday(tok):
    """Parse a WEEKLY BYDAY token: a plain code with no ordinal allowed."""
    if not isinstance(tok, str) or tok not in _WEEKDAY:
        raise ValueError("malformed WEEKLY BYDAY token: %r" % (tok,))
    return _WEEKDAY[tok]


def _monthly_byday(tok):
    """Parse a MONTHLY BYDAY token like '2TU' or '-1FR' into (ordinal, weekday)."""
    if not isinstance(tok, str) or len(tok) < 3 or tok[-2:] not in _WEEKDAY:
        raise ValueError("malformed MONTHLY BYDAY token: %r" % (tok,))
    try:
        ordinal = int(tok[:-2])
    except ValueError:
        raise ValueError("malformed MONTHLY BYDAY ordinal: %r" % (tok,))
    if ordinal == 0 or ordinal < -5 or ordinal > 5:
        raise ValueError("MONTHLY BYDAY ordinal out of range: %r" % (tok,))
    return ordinal, _WEEKDAY[tok[-2:]]


def _month_length(year, month):
    return calendar.monthrange(year, month)[1]


def _ordinal_weekday(year, month, ordinal, weekday):
    """Date of the ordinal-th ``weekday`` of the month, or None if absent.

    ordinal > 0 counts from the start (1 = first); ordinal < 0 counts from
    the end (-1 = last). No clamping: if the requested occurrence does not
    exist, None is returned.
    """
    length = _month_length(year, month)
    if ordinal > 0:
        first = datetime.date(year, month, 1).weekday()
        day = 1 + (weekday - first) % 7 + (ordinal - 1) * 7
        return datetime.date(year, month, day) if day <= length else None
    last = datetime.date(year, month, length).weekday()
    day = length - (last - weekday) % 7 + (ordinal + 1) * 7
    return datetime.date(year, month, day) if day >= 1 else None


def _bymonthday_date(year, month, n):
    """Date for a BYMONTHDAY value ``n`` (positive or negative), or None.

    Negative counts from the end (-1 = last day). If the resolved day does
    not exist in the month, None is returned (no clamping).
    """
    length = _month_length(year, month)
    day = n if n > 0 else length + 1 + n
    if 1 <= day <= length:
        return datetime.date(year, month, day)
    return None


def _candidate_dates(freq, interval, dtstart, weekdays, ordinals, bymonthday):
    """Yield pattern dates in globally ascending order.

    The first WEEKLY/MONTHLY period may yield dates earlier than ``dtstart``
    (the caller filters those out). Generation stops at the calendar's edge.
    """
    if freq == "DAILY":
        step = datetime.timedelta(days=interval)
        day = dtstart
        while True:
            yield day
            try:
                day = day + step
            except OverflowError:
                return

    elif freq == "WEEKLY":
        offsets = weekdays if weekdays is not None else (dtstart.weekday(),)
        monday = dtstart - datetime.timedelta(days=dtstart.weekday())
        step = datetime.timedelta(weeks=interval)
        while True:
            for wd in offsets:
                yield monday + datetime.timedelta(days=wd)
            try:
                monday = monday + step
            except OverflowError:
                return

    else:  # MONTHLY
        base = dtstart.year * 12 + (dtstart.month - 1)
        k = 0
        while True:
            index = base + k * interval
            year, month = index // 12, index % 12 + 1
            if year > _MAX_YEAR:
                return
            days = set()
            if bymonthday:
                for n in bymonthday:
                    d = _bymonthday_date(year, month, n)
                    if d is not None:
                        days.add(d)
            elif ordinals:
                for ordinal, weekday in ordinals:
                    d = _ordinal_weekday(year, month, ordinal, weekday)
                    if d is not None:
                        days.add(d)
            else:
                if dtstart.day <= _month_length(year, month):
                    days.add(datetime.date(year, month, dtstart.day))
            for d in sorted(days):
                yield d
            k += 1


def expand(rule, dtstart, limit):
    freq = rule.get("FREQ")
    if freq not in _FREQ:
        raise ValueError("unknown or missing FREQ: %r" % (freq,))

    interval = rule.get("INTERVAL", 1)
    if isinstance(interval, bool) or not isinstance(interval, int) or interval < 1:
        raise ValueError("INTERVAL must be an int >= 1: %r" % (interval,))

    count = rule.get("COUNT")
    until = rule.get("UNTIL")
    bymonth = rule.get("BYMONTH")
    bymonthday = rule.get("BYMONTHDAY")
    byday = rule.get("BYDAY")

    # Validate BYMONTHDAY values (range check applies whenever present).
    if bymonthday is not None:
        for n in bymonthday:
            if (isinstance(n, bool) or not isinstance(n, int)
                    or not (1 <= n <= 31 or -31 <= n <= -1)):
                raise ValueError("BYMONTHDAY value out of range: %r" % (n,))

    # BYMONTHDAY and BYDAY cannot be combined under MONTHLY.
    if freq == "MONTHLY" and bymonthday and byday:
        raise ValueError("MONTHLY may not combine BYMONTHDAY and BYDAY")

    # Parse BYDAY per FREQ. (DAILY does not define BYDAY, so it is ignored.)
    weekdays = None   # WEEKLY: sorted weekday numbers
    ordinals = None   # MONTHLY: list of (ordinal, weekday)
    if byday:
        if freq == "WEEKLY":
            weekdays = sorted(_weekly_weekday(t) for t in byday)
        elif freq == "MONTHLY":
            ordinals = [_monthly_byday(t) for t in byday]

    months = set(bymonth) if bymonth else None

    target = limit if count is None else min(limit, count)
    result = []
    if target <= 0:
        return result

    for cand in _candidate_dates(freq, interval, dtstart,
                                 weekdays, ordinals, bymonthday):
        if cand < dtstart:
            continue
        if until is not None and cand > until:
            break
        if months is not None and cand.month not in months:
            continue
        result.append(cand)
        if len(result) >= target:
            break
    return result
